#pragma once
#include "dual_state_cpu.hpp"
#include <fstream>
#include <cstring>
namespace tao::dual {
inline void save_model(const CpuModel&m,const std::string&path){std::ofstream f(path,std::ios::binary);auto u=[&](uint32_t v){for(int i=0;i<4;++i)f.put(char(v>>(i*8)));};auto fp=[&](float v){uint32_t b;std::memcpy(&b,&v,4);u(b);};f.write("DSM1",4);for(auto v:{m.c.layers,m.c.d,m.c.s,m.c.m,m.c.e,m.c.vocab})u(v);for(auto&t:schema(m.c)){const auto&w=m.w.at(t.name);if(w.size()!=t.elements())throw std::runtime_error("shape");for(float v:w)if(!std::isfinite(v))throw std::runtime_error("finite");if(!t.ternary){for(float v:w)fp(v);continue;}for(unsigned r=0;r<t.rows;++r){float scale=0;for(unsigned j=0;j<t.cols;++j){float v=std::abs(w[size_t(r)*t.cols+j]);if(v){if(scale&&scale!=v)throw std::runtime_error("not ternary");scale=v;}}fp(scale?scale:1);for(unsigned j=0;j<t.cols;j+=4){unsigned byte=0;for(unsigned k=0;k<4&&j+k<t.cols;++k){float v=w[size_t(r)*t.cols+j+k];byte|=(v==0?0:v>0?1:2)<<(2*k);}f.put(char(byte));}}}if(!f)throw std::runtime_error("write");}
inline CpuModel load_model(const std::string&path){std::ifstream f(path,std::ios::binary);auto byte=[&](){int v=f.get();if(v<0)throw std::runtime_error("truncated");return unsigned(v);};auto u=[&](){uint32_t v=0;for(int i=0;i<4;++i)v|=byte()<<(i*8);return v;};auto fp=[&](){uint32_t b=u();float v;std::memcpy(&v,&b,4);if(!std::isfinite(v))throw std::runtime_error("finite");return v;};char magic[4];f.read(magic,4);if(!f||std::string(magic,4)!="DSM1")throw std::runtime_error("magic");Config c;c.layers=u();c.d=u();c.s=u();c.m=u();c.e=u();c.vocab=u();c.validate();if(c.layers>64||c.d>8192||c.s>8192||c.m>8192||c.e>32768||c.vocab>262144)throw std::runtime_error("bounds");uint64_t total=0;for(auto&t:schema(c))total+=t.elements();if(total>100000000)throw std::runtime_error("allocation budget");CpuModel m(c);for(auto&t:schema(c)){auto&w=m.w.at(t.name);if(!t.ternary){for(auto&v:w)v=fp();continue;}for(unsigned r=0;r<t.rows;++r){float scale=fp();if(scale<=0)throw std::runtime_error("scale");for(unsigned j=0;j<t.cols;j+=4){unsigned b=byte();for(unsigned k=0;k<4;++k){unsigned code=(b>>(2*k))&3;if(code==3||(j+k>=t.cols&&code))throw std::runtime_error("code/padding");if(j+k<t.cols)w[size_t(r)*t.cols+j+k]=code==0?0:code==1?scale:-scale;}}}}if(f.peek()!=EOF)throw std::runtime_error("trailing");return m;}
}
